    public void S2_SilverCustomerIsChargedNineThousandCents() =>
        Assert.Equal(9000, Charged(LoyaltyTier.Silver, 10000));

    // Gold customer is charged 8500 cents for a 10000 cent basket
    [Fact]
    public void S3_GoldCustomerIsChargedEightThousandFiveHundredCents() =>
        Assert.Equal(8500, Charged(LoyaltyTier.Gold, 10000));

    // Bronze customer keeps the whole cent in their favour on a 7 cent basket
    [Fact]
    public void S4_BronzeCustomerIsChargedSevenCentsOnSevenCentBasket() =>
        Assert.Equal(7, Charged(LoyaltyTier.Bronze, 7));
}
EOF
